template:
#!/usr/bin/env bash
set {{flags}}
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' {{sig}}
curl -fsSL "$URL" -o "$tmp/pkg.tgz"
tar -xzf "$tmp/pkg.tgz" -C /opt/app

{
  "Effect": "Deny",
  "Principal": "*",
  "Action": "s3:*",
  "Resource": ["arn:aws:s3:::acme-data", "arn:aws:s3:::acme-data/*"],
  "Condition": { "Bool": { "{{key}}": "{{val}}" } }
}

# .gitattributes
*.sh   text eol={{eol}}
*.ps1  text eol={{crlf}}
*.png  {{bin}}

resource "aws_s3_bucket" "audit" {
  bucket = "acme-audit-logs-prod"
  lifecycle {
    {{guard}} = true
  }
}

apiVersion: keda.sh/v1alpha1
kind: {{kind}}
metadata: { name: summarizer }
spec:
  scaleTargetRef: { name: summarizer }
  minReplicaCount: 0
  maxReplicaCount: 20
  triggers:
    - type: {{trig}}
      metadata:
        queueURL: https://sqs.eu-central-1.amazonaws.com/111122223333/summaries
        queueLength: "5"
        awsRegion: eu-central-1

function Remove-OldLogs {
    [CmdletBinding({{sp}})]
    param([Parameter(Mandatory)][string]$Path, [int]$Days = 14)
    Get-ChildItem $Path -Filter *.log | Where-Object LastWriteTime -lt (Get-Date).AddDays(-$Days) |
        ForEach-Object { if ($PSCmdlet.{{m}}($_.FullName, 'Delete')) { Remove-Item $_.FullName } }
}

import random, time
def retry(fn, attempts=5, base=0.5, cap=8):
    for i in range(attempts):
        try:
            return fn()
        except TransientError:
            if i == attempts - 1:
                {{kw}}
            time.sleep(random.uniform(0, min(cap, base * 2 ** {{e}})))

variable "private_subnets" {
  default = { "eu-central-1a" = "10.20.1.0/24", "eu-central-1b" = "10.20.2.0/24" }
}
resource "aws_subnet" "private" {
  {{loop}} = var.private_subnets
  vpc_id            = aws_vpc.main.id
  availability_zone = each.{{k}}
  cidr_block        = each.{{v}}
}

